const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');
const html=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8');
const start=html.indexOf('function PlanWorkspace('),end=html.indexOf('function Workouts(',start);
assert(start>0&&end>start,'Plano tem componente de apresentação isolado');
const h=(type,props,...children)=>({type,props:props||{},children});
const ctx={React:{createElement:h},isTravelCycle:()=>false,PauseManager:'PauseManager',TrainingCycleGuide:'TrainingCycleGuide',PlanDayCard:'PlanDayCard'};
vm.createContext(ctx);vm.runInContext(html.slice(start,end)+'\nthis.render=PlanWorkspace;',ctx);
const state={profile:{manualPauses:[]}};
const plano=Array.from({length:5},(_,i)=>({day:['Segunda','Terça','Quarta','Quinta','Sexta'][i],name:'Dia '+i,ex:[]}));
let chosen=null;
const tree=ctx.render({state,update:()=>{},plano,planDay:0,setPlanDay:i=>chosen=i,cycleWeek:1,activeCycleStart:'2026-11-09',setPlanName:()=>{},setPlanEx:()=>{},addPlanEx:()=>{},delPlanEx:()=>{},reorderPlanEx:()=>{}});
const walk=(n,accept)=>n&&typeof n==='object'?(accept(n)?[n]:[]).concat(...(n.children||[]).flat(Infinity).flatMap(c=>walk(c,accept))):[];
assert.equal(walk(tree,n=>n.type==='PlanDayCard').length,1,'mantém cartão editável do dia');
const details=walk(tree,n=>n.type==='details');
assert.equal(details.length,2,'separa calendário e progressão');
assert.equal(walk(details[0],n=>n.type==='PauseManager').length,1);
assert.equal(walk(details[1],n=>n.type==='TrainingCycleGuide').length,1);
assert.equal(details[0].props.open,undefined,'calendário fica consultável sem dominar o ecrã');
const days=walk(tree,n=>n.type==='button'&&n.props.className.startsWith('dp'));
assert.equal(days.length,5);days[2].props.onClick();assert.equal(chosen,2,'seletor continua funcional');
const coach=html.slice(html.indexOf('function Coach2027('),html.indexOf('/* =============================== OBJETIVOS'));
assert(coach.indexOf('className:"card coach27-hero"')<coach.indexOf('React.createElement(CoachBlockGuide,{state})'),'estado/próxima ação antes do guia');
assert(coach.indexOf('className:"card coach27-hero"')<coach.indexOf('className:"card evf-nutrition-guide"'),'decisão acima da explicação nutricional');
assert.match(coach,/React\.createElement\("div",\{className:"card coach27-hero"\}/,'estado mostrado mesmo sem tendências');
assert.match(coach,/className:"evf-coach-measure-disclosure"/);
assert.match(html,/className:"evf-training-calendar"/,'contexto de viagem fica consultável');
console.log('Apresentação: Treinar, Plano e Coach organizados sem perder componentes ou ação do seletor.');
